# ---- Agent L3: our layers, each in its own namespace ----
import base64 as _l2_b64
import zlib as _l2_zlib

_L2_SRC = {
    "market_front": "",
    "animals": "",
    "wheat_rt": "",
    "outfarm": "",
    "labour": "",
    "shadow": "",
    "m_sell": "",
    "own_book": "",
    "shed_guard": "",
    "place_guard": "",
    "draw_last": "",
    "tomato_annex": "",
    "safety": "",
}
_L3_LIBRARY = ('A', 'nb_arsgorynich_herdsafe_v3', 'nb_haideptry_2965', 'nb_guru_master_v4', 'nb_dmitrii_herdsafe_2700', 'nb_nihilistic_robust', 'nb_tschinkel_metav4_v13', 'nb_ahmed_v55', 'nb_statma_herd_safe_sale_window_submit', 'nb_statma_herd_safe_sale_window_race_ca20', 'nb_ahmedberatoz_v56_smarter_seeds_and_fertilizer', 'nb_arsgorynich_order_book_v3_response_improvement', 'nb_ahmedberatoz_v57_funding_order_invariant', 'nb_ahmedberatoz_v54_productive_wheat_and_patient', 'nb_haodou092_harvest_ledger', 'nb_haideptry_the_2965_master_hybrid_engine', 'nb_hosen42_v11_hc1_vs_h5_validation', 'nb_haodou092_harvest_ledger_r0930')
_L3_SOURCES = {
    "A": "",
    "nb_arsgorynich_herdsafe_v3": "",
    "nb_haideptry_2965": "",
    "nb_guru_master_v4": "",
    "nb_dmitrii_herdsafe_2700": "",
    "nb_nihilistic_robust": "",
    "nb_tschinkel_metav4_v13": "",
    "nb_ahmed_v55": "",
    "nb_statma_herd_safe_sale_window_submit": "",
    "nb_statma_herd_safe_sale_window_race_ca20": "",
    "nb_ahmedberatoz_v56_smarter_seeds_and_fertilizer": "",
    "nb_arsgorynich_order_book_v3_response_improvement": "",
    "nb_ahmedberatoz_v57_funding_order_invariant": "",
    "nb_ahmedberatoz_v54_productive_wheat_and_patient": "",
    "nb_haodou092_harvest_ledger": "",
    "nb_haideptry_the_2965_master_hybrid_engine": "",
    "nb_hosen42_v11_hc1_vs_h5_validation": "",
    "nb_haodou092_harvest_ledger_r0930": "",
}


def _l2_source(blob):
    return _l2_zlib.decompress(_l2_b64.b64decode(blob)).decode("utf-8")


def _l2_ns(name, inject=None):
    ns = {"__name__": "l2_" + name}
    ns.update(inject or {})
    exec(compile(_l2_source(_L2_SRC[name]), "l2_" + name, "exec"), ns)
    return ns


# Compile every library program once, at load time.
_L3_CODE = {name: compile(_l2_source(blob), "library_" + name, "exec")
            for name, blob in _L3_SOURCES.items()}


def _l3_make(name):
    """A fresh (namespace, entry) for a library program -- exactly what the
    local shadow's factory returns for it."""
    if name == "A":
        env = {}
        exec(_L3_CODE[name], env)
        return env, [v for v in env.values() if callable(v)][-1]
    env = {"__name__": "shadow_" + name, "__file__": "rl/public/" + name + ".py"}
    exec(_L3_CODE[name], env)
    if "NAMESPACE" in env and "KAGGLE_ENTRY" in env:
        return env["NAMESPACE"], env["KAGGLE_ENTRY"]
    return env["agent"].__globals__, env["agent"]


# One pristine instance of each program, built at load time and handed to
# the shadow on turn 0; later requests (a new game in the same process) build
# fresh ones.
_L3_POOL = {name: [_l3_make(name)] for name in _L3_LIBRARY}


def _l3_factory(name):
    def make():
        pool = _L3_POOL.get(name)
        return pool.pop() if pool else _l3_make(name)
    return make


_L3_FACTORIES = {name: _l3_factory(name) for name in _L3_LIBRARY}
_L2_ENV = globals()
_L2 = {}
_L2["market_front"] = _l2_ns("market_front", {})
_L2["animals"] = _l2_ns("animals", {})
