_l2_agent = _L2["market_front"]["mf_wrap"](_l2_agent, sell_first=('FERTILIZER',), cap_counters=True, wheat_weight=0.25, wheat_adapt=True)
_l2_agent = _L2["labour"]["lb_wrap"](_l2_agent)
_l2_agent = _L2["shadow"]["shadow_wrap"](_l2_agent, programs=_L3_LIBRARY,
                                         reorder=True, early=True,
                                         factories=_L3_FACTORIES, early_when_agree=True, early_now=True)
_l2_agent = _L2["m_sell"]["m_sell_wrap"](_l2_agent, after_beaten=True, beaten_any=True)
